#!/usr/bin/env python3
"""Film Part 2: Screenwriting Intelligence, Editing, Post-Production -- pairs for upgrade_b"""
import json, pathlib

OUT = pathlib.Path('/workspace/data_upgrades/upgrade_b.jsonl')
OUT.parent.mkdir(parents=True, exist_ok=True)

pairs = [
# ── SCRIPT FORMATTING ─────────────────────────────────────────────────────────
("Explain professional screenplay formatting and why it matters.", "Professional screenplay formatting is standardised to allow industry readers to estimate production cost, pacing, and shoot requirements at a glance. Standard rules (US feature film): (1) Page = approximately 1 minute of screen time (a 105-page script = approximately 105-minute film); this convention means formatting precision directly affects runtime estimation. (2) Courier 12pt font -- fixed-width font so that line counts per page are consistent across all scripts. (3) Page layout -- 1.5\" left margin, 1\" right, 1\" top and bottom. (4) Scene heading (slug line) -- INT./EXT. LOCATION -- DAY/NIGHT; all caps; left-aligned at margin. (5) Action lines -- describe what is seen and heard; present tense; active voice; no camera directions unless the director is also the writer; keep to 3-4 lines maximum per action block. (6) Character cue -- centred, all caps, 4.2\" from left; appears immediately above dialogue. (7) Dialogue -- centred under character cue, 2.5\" from left, 2.5\" right margin. (8) Parenthetical -- actor direction in parentheses under character cue; used sparingly (only when tone is not obvious from context); overuse is a mark of amateur writing. (9) Transition -- FADE IN: at the beginning; FADE OUT. at the end; CUT TO: used rarely for emphasis. Software: Final Draft, Highland 2, WriterDuet, Fade In -- all enforce these standards automatically."),
("How do beat sheets work and how do you use them for script development?", "A beat sheet is a structured outline of a screenplay's key story moments (beats) before writing the full script. It captures the essential story events in sequence without dialogue or scene description -- typically 1-3 sentences per beat. Purpose: (1) Story architecture validation -- identifying structural problems (a weak midpoint, a missing all-is-lost moment, an unresolved character arc) in a beat sheet takes hours; finding the same problems in a full draft takes weeks. (2) Collaborative development -- producers, directors, and writers can align on story before the investment of a full draft. (3) Pacing analysis -- the density or sparsity of beats in different story sections reveals pacing problems; too many beats in Act 1 = overloaded setup; too few in Act 2B = a sagging middle. Blake Snyder's Save the Cat beat sheet (15 beats): Opening Image; Theme Stated; Set-Up; Catalyst (inciting incident); Debate; Break into Act 2; B Story; Fun and Games; Midpoint; Bad Guys Close In; All Is Lost; Dark Night of the Soul; Break into Act 3; Finale; Final Image. Alternative frameworks: three-act (simpler); seven-point story structure; the Sequence Approach (8 sequences of 10-15 minutes). Using it: writers spend 2-4 weeks developing the beat sheet before drafting; directors use it to evaluate a script's structural logic without reading line by line; producers use it to pitch to studios."),
("Explain scene objectives and how they drive dramatic writing.", "Scene objective is what a character wants from the other character in the scene -- their immediate, specific goal within the scene's duration. It is distinct from the character's overall story goal (want) or internal need (need). The scene objective creates dramatic conflict when two characters in the same scene have opposing or incompatible objectives. Writing with objectives: (1) Every character in every scene should have a clear, active objective that can be stated as a transitive verb: 'Sarah wants to CONVINCE Marcus to stay'; 'Marcus wants to ESCAPE Sarah's guilt.' The verb must be playable by an actor. (2) Objectives create subtext -- if both characters stated their objectives directly, the scene would be over in two lines; subtext is what happens when characters pursue their objectives indirectly, through social conventions, deflection, manipulation, or vulnerability. (3) Objectives shift at beats -- when the current tactic fails (Sarah's logic fails to convince Marcus), the character shifts tactics and possibly shifts the objective's priority (Sarah shifts to MANIPULATE Marcus using emotional memory). (4) The scene's climax is the moment of decisive action or decisive avoidance -- one objective wins or both lose. (5) Scene objectives are distinct from arc objectives -- a character can want comfort in a scene while their arc requires them to face pain; this tension between scene objective and arc creates the most powerful dramatic moments. For a director: identifying each character's objective is the first step in actor communication ('What do you want from her in this scene?')."),
("Explain subtext detection in screenplay analysis.", "Subtext is what a character means versus what they say -- the gap between surface dialogue and underlying intention, feeling, or information. Detecting subtext in an existing script: (1) Read dialogue and ask: would a real person in this situation say this directly? If yes, there is no subtext -- the writing is on the nose. If the character would more likely avoid this direct statement, what are they really communicating through their chosen words? (2) Look for deflection patterns -- a character who responds to 'Do you love me?' with 'I made dinner' is communicating something through the deflection; what? Guilt? Practical love? Inability to verbalise? (3) Look for over-precision -- characters who are very precise about one thing while vague about another are often avoiding the vague thing. (4) Look for silences (action lines with no dialogue) -- what is happening in the silence? What is the character preventing themselves from saying? (5) Examine what characters do while they speak -- if a character is washing dishes while discussing divorce, the physical activity is the emotional avoidance; the subtext is in the gap between the mundane action and the charged words. (6) Character history -- subtext is created by what the characters know about each other that the audience learns gradually; a line of ordinary dialogue becomes charged once the audience understands the history. Director's use of subtext analysis: once subtext is identified, the director and actor agree on what the character is really feeling; the actor plays the subtext; the dialogue is the mask over it."),
("How do you map emotional pacing in a screenplay?", "Emotional pacing maps the audience's emotional journey through the script -- the rhythm of tension, release, uplift, dread, comedy, and sorrow across the film's duration. Analysis process: (1) Read through the script marking each scene's primary emotional key (tension, comedy, sadness, joy, dread, excitement, confusion); assign an intensity value (1-5). (2) Graph the emotional arc -- plot intensity over time; a well-paced script creates a wave pattern: intensity builds, releases, builds higher, releases, builds to the climax. A flat line (all scenes at intensity 3) is boring; sustained high intensity without release is numbing. (3) Identify pacing problems: (a) Three consecutive high-intensity scenes without relief = audience fatigue; insert a scene of lower intensity (comedy beat, quiet character moment) to provide contrast. (b) A dead zone (five scenes at intensity 1) in Act 2B = the film's most common structural problem; this section needs higher stakes or a more active antagonist. (c) Emotional key repetition -- four consecutive sad scenes exhaust a single emotion; diversify emotional keys to create contrast that makes each emotion more potent when it returns. (4) Comedy beats as structural tool -- comedic relief is not decoration; it resets emotional capacity, allows the audience to breathe, and makes the return to dramatic intensity more powerful. (5) The midpoint emotional reversal -- a film that is going in one emotional direction should reverse course at the midpoint; this is the engine of second-act engagement. Director's application: the emotional pacing map becomes the guide for tone conversations with the composer, editor, and sound designer."),
("How do you analyse conflict in a screenplay?", "Conflict analysis -- the skeleton beneath the screenplay's surface: (1) Three levels of conflict: internal (character vs themselves: a character's contradictory desires, fears, and values); interpersonal (character vs another character: opposing objectives, history, power dynamics); external (character vs world: society, nature, institutions, technology). The most compelling screenplays operate on all three levels simultaneously; the external conflict is the vehicle through which the internal conflict is resolved. (2) Primary conflict identification -- the film's central conflict is the force that the protagonist must overcome or succumb to to reach their arc's endpoint. Naming it precisely: not 'Sarah vs the corporation' but 'Sarah vs her own fear of being seen as weak, embodied by her boss who represents everything she was taught to be.' (3) Scene-level conflict -- every scene should contain at least one conflict, even if it is subtle; a scene with no conflict is a scene without dramatic function. Conflict does not mean argument; conflict means two forces in opposition. (4) Conflict escalation -- tracking the escalation of the primary conflict from scene to scene; the conflict should intensify as the film progresses, reaching its maximum intensity at the climax. (5) Conflict and character revelation -- how a character responds to conflict reveals character; the greater the conflict, the deeper the character revelation. (6) Mapping conflict graphically: a three-column chart (scene / primary conflict / character choice made) shows how the protagonist's choices escalate the conflict and drive toward the climax."),
("What is script breakdown by department and how is it produced?", "Script breakdown is the systematic extraction of every production element required from the screenplay, organised by department. It is produced by the 1st AD (or breakdown coordinator) using Movie Magic Scheduling or similar software. Department categories per scene: (1) Cast -- every named character who appears in the scene, listed by character and actor name; differentiated by type (Day Player, Weekly, Supporting, Extra). (2) Extras (background action) -- number and description ('20 PEDESTRIANS', '6 DINER CUSTOMERS'). (3) Props -- every physical object handled by an actor or required to be visible ('NEWSPAPER, COFFEE CUP, REVOLVER'); props department sources, rents, or makes every listed prop. (4) Set dressing -- the environment's furnishing ('ANTIQUE DESK', 'FRAMED PHOTOGRAPHS'). (5) Costumes -- specific wardrobe noted in the scene ('SARAH in her RED COAT'). (6) Vehicles -- any moving or parked vehicle that appears on screen. (7) Special effects -- any physical practical effect: rain, fire, explosions, breakaway glass. (8) VFX -- any shot requiring visual effects post-production; noted with specific description for the VFX supervisor. (9) Stunts -- any action requiring a stunt performer or safety consultation. (10) Animals -- any animal (performing or background). (11) Special equipment -- camera cranes, underwater housing, helicopter rigs. The breakdown is converted into production strips (one per scene) that are colour-coded by time of day (day/night/exterior/interior) and used to build the shooting schedule."),
("Explain script revision comparison and version control for productions.", "Script revision management: In professional production, every change to the script is formally tracked and distributed as a revised set of pages. The system: (1) Revision colours -- the industry-standard colour-coded revision sequence: White (original), Blue (1st rev), Pink (2nd), Yellow (3rd), Green (4th), Goldenrod (5th), Buff (6th), Salmon (7th), Cherry (8th); then the cycle repeats with double colours: Double Blue, Double Pink, etc. All crew work from the current coloured pages; when a scene changes, only the changed pages are reprinted in the new colour and distributed. (2) Asterisk markers -- changed lines within a revision are marked with an asterisk (*) in the right margin; allows the crew to see precisely what changed without re-reading the entire page. (3) Scene number permanence -- once scene numbers are assigned for production, they never change even if scenes are moved, deleted, or added; deleted scenes are marked OMITTED; added scenes between existing scenes get letter suffixes (Scene 45A inserted between 45 and 46). (4) Production draft vs development draft -- the production draft is locked at the start of principal photography and changes thereafter are formal revisions; development drafts are informal and numbered by draft number ('First Draft', 'Second Draft'). Digital version control: WriterDuet and Final Draft support cloud collaboration with version history; Frame.io and Celtx support production-level script management. For the director: always confirm the current revision date on every page before rehearsal or coverage planning; shooting from an outdated draft is a production error."),

# ── EDITING AND POST-PRODUCTION ───────────────────────────────────────────────
("Explain how a director covers a scene for the edit.", "Covering a scene for the edit means capturing enough material in enough angles and sizes that the editor has genuine options to construct the scene's best possible version. The editor's tools are: (1) The ability to cut on action (a movement that can be shown in two different shots at the point of the action's peak); (2) The ability to shift emotional scale (cut from MS to CU for emotional escalation); (3) The ability to redirect attention (cut to a reaction rather than the speaker); (4) Rhythm control (control pacing through selection of which takes to use). What an editor needs: (a) At least two sizes of coverage for every significant beat (a moment covered only in a wide shot cannot be elevated to a close-up in the edit); (b) Reaction shots (an actor's reaction is often more powerful than the action they are responding to; coverage of the listening character is as important as the speaking character); (c) Clean entrances and exits (characters walking into and out of frame completely; gives the editor clean cut points); (d) Takes with different energy levels (one take at full emotional intensity, one more restrained; the editor decides which serves the rhythm); (e) Overlapping action (both the previous shot and the next shot should cover a specific action so the editor has multiple cut points). The director's responsibility: communicate clearly to the DP which moments need special coverage emphasis."),
("How does editorial continuity affect on-set decisions?", "Editorial continuity is the set of spatial, physical, and temporal consistencies that the editor needs to cut the film so it feels like a single reality. On-set decisions that affect editorial continuity: (1) Screen direction -- if a car drives left to right in one shot and right to left in the next, it appears to have turned around; all on-set coverage must maintain consistent screen direction within a sequence. (2) Match cuts -- if an actor reaches for a glass in the master and the CU shows the same action, both takes must reach at the same pace and starting position; the script supervisor marks which takes have clean match cuts at which moments. (3) Dialogue overlap -- if an actor finishes a line early in one take, the editor will need the next shot to pick up from the right moment in the dialogue; ensure coverage of both the end of one line and the beginning of the next in each shot. (4) Physical state continuity -- a wound, a prop's position, a costume element; if changed between takes for any reason (accidental or intentional), document the discrepancy; the editor may not be able to cut between shots with mismatched physical state. (5) Background continuity -- extras and background movement should be consistent between master and close-ups filmed hours apart; the script supervisor monitors this. (6) Light continuity -- exterior scenes shot across multiple hours may have significantly different light quality between the master (shot at 9 AM) and the CUs (shot at noon); alert the DP before moving to coverage."),
("Explain the role of pacing in a film edit and how editors control it.", "Pacing in editing is the rate at which information is delivered to the audience -- the rhythm of cuts that controls whether a film feels fast or slow, urgent or contemplative. Elements editors control: (1) Cut frequency (the number of cuts per unit time) -- a scene with 20 cuts per minute feels urgent; a scene with 3 cuts per minute feels slow and weighted. Neither is inherently better; both serve specific dramatic purposes. (2) Cut placement (exactly where within an action or line of dialogue the cut occurs) -- cutting before a pause ends creates urgency; cutting after the pause plays the moment's full weight. Cutting on the peak of an action creates kinetic impact; cutting before the peak creates anticipation. (3) Shot duration -- long takes force the audience to stay with an image and find the meaning in the duration; Tarkovsky's long takes create contemplative depth. Short takes create cumulative rhythm and can substitute for complex choreography. (4) Intercutting rhythm -- the relationship between the pace within two intercut sequences creates meaning through contrast (a slow conversation intercut with a fast car chase creates tension through rhythmic opposition). (5) Structural pacing -- the distribution of fast and slow scenes across the film's total runtime; a good film changes pace frequently enough to prevent either tension fatigue (all fast) or boredom (all slow). (6) Music and pacing -- music creates a tempo that the editing can align with or cut against; cutting against a slow musical phrase with fast edits creates counterpoint; cutting to the beat creates kinetic pleasure."),
("What is an ADR session and when is it used?", "ADR (Automated Dialogue Replacement, also called 'looping' or dubbing) is the process of re-recording dialogue in a studio after production to replace or supplement production sound. When ADR is used: (1) Poor production sound quality -- noise on set (HVAC, aircraft, traffic, crew noise) makes the original recording unusable; the actor re-records the line in sync with the picture in a quiet studio. (2) Creative changes -- a line of dialogue has been changed in the edit for narrative clarity, character, or content reasons; the original production track doesn't contain the new line. (3) Foreign language localisation -- the film is dubbed into other languages. (4) Clarity -- an actor's delivery is unclear (mumbled, spoken too fast, too quiet relative to ambient sound) and production sound cannot be made intelligible. (5) Emotional pitch adjustment -- in rare cases, an actor's performance in the scene was physically right but vocally wrong (too high energy, too quiet); ADR can replace only the vocal performance. Process: actor stands in front of a screen showing the scene; three beeps signal the start of the take (the 'beep-beep-beep' replacement for the traditional analogue loop); actor watches their own performance and matches it in real time; multiple takes, each labelled; best takes are cut into the dialogue edit. The ADR supervisor coordinates which lines are needed; the dialogue editor cuts the ADR takes into the session, matching sync and blending with production sound. Quality: ADR sounds different from production sound (different acoustic environment, different performance energy); good ADR recording and dialogue editing minimises this difference."),
("Explain sequence construction and how editors build emotional arcs within a scene.", "Sequence construction is the editor's craft of assembling individual shots into a coherent, purposeful emotional and narrative experience. The process: (1) Select the best takes -- the editor watches all circled takes for each setup and selects the best performance (which may not be the same as the most technically clean take); flags for the director. (2) Establish the scene's dramatic shape -- identify the scene's beats and where the emotional peak is; the editing should build toward that peak. (3) Build the master layer -- lay in the master shot as the foundation; this provides spatial orientation and reveals the scene's overall rhythm. (4) Cut for performance, not formula -- an editor who cuts mechanically (master, OTS, CU, OTS, CU) is following a formula; a skilled editor listens to the performances and cuts when the camera position best serves what the scene is communicating at that moment. (5) Reaction is the story -- film is often edited on the reaction rather than the action; when a character says something shocking, the story is in the listener's response; cut to the reaction at the peak of the action, or slightly before. (6) Use silence -- the gap between lines, the pause before a decision, the moment after a revelation; editors who cut on every line break lose the emotional weight that lives in silence. (7) Intercutting for tension -- alternating between two characters creates tension and implies a power dynamic (more time on the character who is gaining power). (8) Sound as bridge -- sound often motivates a cut before the visual cut; the audience hears the next scene's ambient sound before they see it; this creates seamless transitions and builds anticipation."),
("Explain pickups, inserts, and how they are used to rescue a scene in post.", "Pickups are additional photography days scheduled after the main production wrap to capture specific shots that are missing, were not captured as planned, or are needed based on discoveries in the edit. Inserts are specific detail shots (a hand turning a key, a close-up of a clock, a letter being opened) that can typically be captured quickly with a small crew without the main cast. Types of pickups: (1) Coverage pickups -- a specific shot that was not captured during production (a reaction shot in a critical scene, a clean entrance needed for an edit). (2) Performance pickups -- a critical scene where none of the production takes works; the entire scene is re-shot with a small crew and the relevant cast. (3) Story pickups -- shots needed because the story or structure has changed in the edit (a new scene to bridge two sequences, an insert to clarify a plot point). (4) VFX plates -- additional photography of locations or backgrounds needed by the VFX department to complete composite shots. Planning pickups effectively: the editor flags all holes in the cut during the editorial process; the director reviews these flags and adds their own observations; the 1st AD schedules a pickup day prioritising the most critical missing elements; the DP matches the lighting of the original production. Insert shooting: a second-unit director often shoots inserts during production or post; the director approves inserts that they did not personally direct. Why inserts matter: a single well-executed insert shot can repair a scene that doesn't work (the close-up of the key in the lock that reveals the character's hesitation can add emotional complexity to an otherwise flat scene)."),
("What is VFX planning in pre-production and how does a director work with the VFX supervisor?", "VFX pre-production planning: (1) Script breakdown for VFX -- the VFX supervisor reads the script and identifies every shot that requires a visual effect, categorised by: practical (in-camera effects that require plate photography or practical elements); compositing (adding or removing elements from photography); CG (computer-generated imagery added to photography); replacement (replacing a photographed element with a digital version). (2) Bid process -- for each VFX shot, the VFX supervisor estimates the cost and complexity; this informs the budget and sometimes requires script revision to reduce VFX scope. (3) Pre-visualisation (pre-vis) -- complex VFX sequences are pre-visualised in 3D: simplified animated versions of the shot sequence showing camera positions, character action, and VFX integration; pre-vis communicates intent to all departments (production designer knows what set must be built vs what will be added digitally; DP knows camera placement for compositing). (4) Plate photography protocol -- every VFX shot requires a photography 'plate' (the physical production element photographed on set) that the VFX team will composite into; the DP must shoot plates with the VFX team's requirements (specific tracking markers, grey and chrome balls for HDR environment capture, neutral lighting for digital element integration). (5) On-set VFX supervision -- a VFX supervisor or on-set VFX coordinator is present for every VFX-affected shoot day; they approve plates, review tracking markers, and ensure the necessary reference elements are captured. (6) Director's visual intent communication -- the director must communicate their visual intent for each VFX shot clearly; the VFX team cannot interpret a vague 'it should feel big' -- they need: scale, lighting mood, motion speed, colour temperature, and any reference images."),
("Explain colour grading and how a director works with a colourist.", "Colour grading is the post-production process of adjusting the colour, contrast, and luminance of a film's image to realise its visual aesthetic. It occurs after picture lock. Process: (1) The colourist works on a calibrated reference display (P3 or Rec2020 colour space) in a grade suite; the DP attends grading sessions; the director attends key sessions and final approval. (2) Primary correction -- establishes the foundational exposure, white balance, and contrast of the image; corrects technical problems from photography (overexposed highlights, underexposed shadows, colour temperature inconsistency). (3) Secondary correction -- selective adjustments to specific colour ranges or masked areas; example: warming skin tone without warming the sky; darkening the background without affecting the faces; adjusting a specific colour (making the red dress more vibrant without affecting other elements). (4) Look creation -- building the film's visual signature: the cinematic 'look' that supports its tone (a warm, golden look for a romantic memory; a cold, desaturated look for a corporate present; a high-contrast noir look for a thriller). (5) Shot-to-shot continuity -- ensuring that cuts between shots in the same scene have visual continuity even if they were photographed at different times or with different exposure settings. (6) Deliverable grades -- the film is graded in different versions for different delivery requirements: theatrical (P3 colour space, HDR), streaming (Rec.709 or HDR10, Dolby Vision), and broadcast. Director's role: attend the first pass of grading on the most visually important sequences; establish tone and direction; trust the DP and colourist for technical decisions; make final approval decisions on look and consistency."),
("Explain post-production workflow dependencies between departments.", "Post-production workflow dependencies -- the map of which deliverables one department needs from another: (1) Picture lock is the foundation -- no locked picture means VFX, music, and sound cannot finalise their work; all changes after picture lock require expensive ripple revisions across departments. (2) VFX dependencies -- VFX requires: locked picture cut (frame-accurate reference), offline editorial cut in EDL or XML format (to conform VFX shots to the edit), approved lookdev (the graded reference so VFX can match the colour space), and on-set reference material (tracking markers, HDR environment captures). VFX delivers back: final VFX shots (at native resolution) to be cut back into the picture. (3) Music dependencies -- the composer requires: picture lock (to score to exact frames), temp score notes (what worked, what didn't, which temp tracks the director loved), and discussions of emotional intent scene by scene. The composer delivers: STEMS (separated instrument layers: strings, brass, percussion, solo) for the music mixer. (4) Sound editorial dependencies -- dialogue editing requires production sound files synced to picture; ADR requires picture lock and ADR supervisor's script; Foley requires picture lock and a Foley recording session (on a Foley stage with picture displayed). Sound effects editing requires picture lock. (5) Mix dependencies -- the mix requires: all audio deliverables (dialogue edited tracks, ADR, Foley, effects, music stems), mixing stage booking, and a picture reference (DCP or ProRes file at full resolution). (6) Deliverables chain -- the completed mix is delivered with the coloured picture to the online editor for final conforming and QC."),

# ── SOUND DESIGN AWARENESS ────────────────────────────────────────────────────
("How does sound design serve a film's storytelling?", "Sound design is as important as the visual image in creating a film's world and emotional experience -- audiences experience film simultaneously through both senses, and manipulating sound creates effects that images alone cannot. Sound design layers: (1) Production sound -- the audio captured on set; primary dialogue; ambient location sound; the 'ground truth' of the acoustic environment. (2) Dialogue -- the cleaned, ADR-supplemented, and balanced vocal track; intelligibility is the first priority; emotional clarity is the second. (3) Room tone / ambience -- every location has a sonic identity; the atmospheric sound layer beneath all other elements; changes in ambience mark scene transitions and location changes even before the picture cuts. (4) Sound effects (SFX) -- specific sounds tied to specific visual events; designed to be either realistic (Saving Private Ryan's hyperrealistic combat sound) or heightened/stylised (Mad Max's operatic industrial sound design). (5) Foley -- sounds that cannot be captured in production (subtle cloth movement, footsteps, specific prop handling) recorded to picture by a Foley artist; adds physical texture and specificity to performance. (6) Music -- works emotionally when sound effects cannot; tells the audience how to feel about ambiguous events; rhythm of the score can drive or counterpoint the editing rhythm. Silence as sound design: the strategic absence of sound is the most powerful tool; the silence before an explosion, the silence that follows a confession, the silence that Kubrick used in 2001 to externalise the void of space. Director's responsibility: develop a 'sound philosophy' in pre-production as clearly as a visual philosophy."),
]

assert len(pairs) >= 20, f"Only {len(pairs)} pairs"
existing = sum(1 for _ in OUT.open()) if OUT.exists() else 0
print(f"Existing pairs: {existing}")

with OUT.open("a") as f:
    for q, a in pairs:
        f.write(json.dumps({"messages": [
            {"role": "user", "content": q},
            {"role": "assistant", "content": a}
        ]}) + "\n")

total = sum(1 for _ in OUT.open())
print(f"Total after film_part2: {total}")
print("Film Part 2 DONE")
